arguments.keystrokes:
bash << 'SCRIPT'
mkdir -p /var/www/html
echo "Welcome to the benchmark webserver" > /var/www/html/index.html
echo "Page not found - Please check your URL" > /var/www/html/404.html
if ! grep -q 'log_format benchmark' /etc/nginx/nginx.conf; then
cat > /tmp/ni.txt << 'EOF'
    log_format benchmark '$time_local $request_method $status "$http_user_agent"';
    limit_req_zone $binary_remote_addr zone=benchmark:10m rate=10r/s;
EOF
sed -i '/^http {/r /tmp/ni.txt' /etc/nginx/nginx.conf
fi
cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
server {
    listen 8080;
    server_name _;
    root /var/www/html;
    index index.html;
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;
    limit_req zone=benchmark burst=10;
    error_page 404 /404.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
nginx -t
nginx -s stop 2>/dev/null
rm -f /run/nginx.pid
sleep 1
nginx
sleep 1
echo "=== Test localhost:8080 ==="
curl -s http://localhost:8080
echo ""
echo "=== Test 404 ==="
curl -s http://localhost:8080/nonexistent
echo ""
echo "Access logs: /var/log/nginx/benchmark-access.log"
SCRIPT
